// Build the client submission folder.
//
// Copies the project into a clean tree, excluding three categories that must
// not leave this machine or would only confuse a reviewer:
//
//   secrets      .env*, .vercel  — credentials, never shipped
//   build output node_modules, .next, caches — regenerated by npm install
//   internal     .superpowers, docs/superpowers, AGENTS.md, CLAUDE.md, .git —
//                working process, not project deliverables
//
// The exclude list is deny-by-default at the top level: anything not named in
// TOP_LEVEL_KEEP is left out, so a new folder appearing in the repo cannot
// silently end up in a client zip.
import fs from 'node:fs';
import path from 'node:path';

const SRC = 'E:/Barang Barang/.PersonalWork/Freelance/Nuha/arah/arah';
const PARENT = 'E:/Barang Barang/.PersonalWork/Freelance/Nuha';
const OUT = path.join(PARENT, 'Delivery');

// Explicit allowlist. Everything else at the repo root is omitted.
const TOP_LEVEL_KEEP = new Set([
  'app', 'components', 'lib', 'ml', 'public', 'scripts', 'services',
  'supabase', 'tests', 'docs',
  'README.md', 'package.json', 'package-lock.json', 'next.config.mjs',
  'vercel.json', 'eslint.config.mjs', 'jsconfig.json', 'postcss.config.mjs',
  'components.json', 'proxy.js', 'pytest.ini', 'requirements-dev.txt',
  // Without this the Vitest suite cannot run at all — caught by listing what
  // the deny-by-default rule had dropped rather than assuming it was right.
  'vitest.config.mjs',
  '.gitignore',
]);

// Paths inside kept folders that must still be dropped.
const NESTED_EXCLUDE = new Set([
  path.join('docs', 'superpowers'),
  path.join('docs', 'PLAN-1-VS-AGREED.md'),
]);

const NAME_EXCLUDE = [
  /^node_modules$/, /^\.next$/, /^\.vercel$/, /^\.git$/, /^\.superpowers$/,
  /^\.pytest_cache$/, /^__pycache__$/, /^\.env/, /^\.DS_Store$/,
];

let copied = 0;
let skipped = [];

function excludedByName(name) {
  return NAME_EXCLUDE.some((re) => re.test(name));
}

function copyDir(srcDir, outDir, rel = '') {
  fs.mkdirSync(outDir, { recursive: true });
  for (const entry of fs.readdirSync(srcDir, { withFileTypes: true })) {
    const relPath = path.join(rel, entry.name);
    if (excludedByName(entry.name)) { skipped.push(relPath); continue; }
    if (NESTED_EXCLUDE.has(relPath)) { skipped.push(relPath); continue; }
    if (rel === '' && !TOP_LEVEL_KEEP.has(entry.name)) { skipped.push(relPath); continue; }

    const from = path.join(srcDir, entry.name);
    const to = path.join(outDir, entry.name);
    if (entry.isDirectory()) copyDir(from, to, relPath);
    else { fs.copyFileSync(from, to); copied += 1; }
  }
}

fs.rmSync(OUT, { recursive: true, force: true });
fs.mkdirSync(OUT, { recursive: true });

// 1. Source code
copyDir(SRC, path.join(OUT, 'source-code'));

// 2. Datasets, surfaced at the top level as well — the brief asks for them by
//    name and a reviewer should not have to know they live under ml/data.
const dataOut = path.join(OUT, 'datasets');
fs.mkdirSync(path.join(dataOut, 'reference'), { recursive: true });
fs.copyFileSync(path.join(SRC, 'ml/data/survey.csv'), path.join(dataOut, 'survey.csv'));
for (const f of fs.readdirSync(path.join(SRC, 'ml/data/reference'))) {
  fs.copyFileSync(
    path.join(SRC, 'ml/data/reference', f),
    path.join(dataOut, 'reference', f)
  );
}

// 3. Presentations
const presOut = path.join(OUT, 'presentation');
fs.mkdirSync(presOut, { recursive: true });
for (const f of ['ARAH-Pitch.pptx', 'ARAH-System-Overview.pptx']) {
  const from = path.join(PARENT, f);
  if (fs.existsSync(from)) fs.copyFileSync(from, path.join(presOut, f));
}

// 4. The original survey export the project started from.
const srcSurvey = path.join(PARENT, 'Post-SPM Academic Pathway and Interest Survey.csv');
if (fs.existsSync(srcSurvey)) {
  fs.copyFileSync(srcSurvey, path.join(dataOut, 'Post-SPM Academic Pathway and Interest Survey (original export).csv'));
}

// 5. The folder's own guide. Sourced from the repo rather than written here,
//    so it is version-controlled and cannot be lost when this script wipes
//    and rebuilds the output directory.
fs.copyFileSync(path.join(SRC, 'docs/DELIVERY-README.md'), path.join(OUT, 'README.md'));
copied += 1;

console.log(`copied ${copied} files into ${OUT}`);
console.log('\nomitted at the top level:');
console.log('  ' + [...new Set(skipped.filter((s) => !s.includes(path.sep)))].sort().join('\n  '));
console.log('\nomitted nested:');
console.log('  ' + [...new Set(skipped.filter((s) => s.includes(path.sep)))].sort().slice(0, 12).join('\n  '));
